// arc_src.h is generated by run_tests.sh from the real Marlin_main.cpp and motion_control.cpp
#include "arc_src.h"
#include <assert.h>
int main()
{
  recalc_delta_settings(delta_radius, delta_diagonal_rod);
  // 1. reachable <=> calculate_delta gives no NaN, on a fine grid far beyond the printable area
  int mism = 0, n = 0, out = 0;
  for (float x = -299.9; x <= 300; x += 2.5)
    for (float y = -299.9; y <= 300; y += 2.5)
      for (float z = 0; z <= 250; z += 125) {
        float c[3] = {x, y, z};
        calculate_delta(c);
        bool nan = isnan(delta[0]) || isnan(delta[1]) || isnan(delta[2]);
        bool r = delta_reachable(c);
        n++;
        if (!r) out++;
        if (nan == r) mism++;
      }
  printf("reachable() vs NaN: %d points (%d outside the reach), mismatches: %d\n", n, out, mism);
  assert(mism == 0 && out > 0);
  // 2. an arc that stays inside is planned completely with the Cartesian length of every segment
  float pos[4] = {30, 0, 10, 0}, tgt[4] = {0, 30, 10, 5}, off[4] = {-30, 0, 0, 0};
  mc_arc(pos, tgt, off, X_AXIS, Y_AXIS, Z_AXIS, 50, 30, 0, 0);
  double tot = 0;
  for (auto &s : segs) tot += s.len;
  printf("arc inside: %zu segments, total Cartesian length %.3f mm (a quarter circle of r=30 is %.3f), E at end %.3f (target %.3f)\n", segs.size(), tot, M_PI / 2 * 30, segs.back().e, tgt[3]);
  assert(fabs(tot - M_PI / 2 * 30) < 0.1 && fabs(segs.back().e - tgt[3]) < 1e-4);
  // 3. an arc that leaves the reachable area is stopped: target (the parser position) becomes the last planned point
  segs.clear();
  float pos2[4] = {40, 0, 10, 0}, tgt2[4] = {160, 0, 10, 8}, off2[4] = {60, 0, 0, 0};  // circle of radius 100 around the origin, starting near the edge
  float c0[3] = {40, 0, 10};
  printf("start (40,0,10) reachable: %d\n", delta_reachable(c0));
  mc_arc(pos2, tgt2, off2, X_AXIS, Y_AXIS, Z_AXIS, 50, 60, 0, 0);
  assert(segs.size() > 0 && segs.size() < 315);
  printf("arc through the edge: %zu segments planned, parser position now (%.2f, %.2f, %.2f) E %.3f\n", segs.size(), tgt2[0], tgt2[1], tgt2[2], tgt2[3]);
  {
    float e[3] = {tgt2[0], tgt2[1], tgt2[2]};
    printf("parser position reachable: %d\n", delta_reachable(e));
    assert(delta_reachable(e) && tgt2[3] > 0 && tgt2[3] < 8);
  }
  if (!segs.empty()) {
    float last[3] = {segs.back().c[0], segs.back().c[1], segs.back().c[2]};
    (void)last;
  }
  // 4. the bed mesh moves an arc like any other move: every tower of every segment is raised by the mesh offset at that point
  {
    mesh_have = true;
    for (int k = 0; k < MESH_POINTS; k++) mesh_z[k] = 0.3f * sinf(k * 0.7f) + 0.1f;
    mesh_changed();
    float p[4] = {40, 0, 0.3f, 0}, t[4] = {0, 40, 0.3f, 0}, o[4] = {-40, 0, 0, 0};
    mesh_active = false;
    segs.clear();
    mc_arc(p, t, o, X_AXIS, Y_AXIS, Z_AXIS, 50, 40, 0, 0);
    std::vector<Seg> plain = segs;
    float p2[4] = {40, 0, 0.3f, 0}, t2[4] = {0, 40, 0.3f, 0};
    mesh_active = true;
    segs.clear();
    mc_arc(p2, t2, o, X_AXIS, Y_AXIS, Z_AXIS, 50, 40, 0, 0);
    mesh_active = false;
    double worst = 0, biggest = 0;
    assert(segs.size() == plain.size() && segs.size() > 10);
    for (size_t k = 0; k < segs.size(); k++) {
      float ang = (float)((k + 1) * (M_PI / 2) / segs.size());
      float off_here = mesh_offset(40 * cosf(ang), 40 * sinf(ang));
      for (int a = 0; a < 3; a++) {
        double d = segs[k].c[a] - plain[k].c[a];
        worst = fmax(worst, fabs(d - off_here));
        biggest = fmax(biggest, fabs(d));
      }
    }
    printf("arc with a bed mesh: %zu segments, the towers rise by up to %.3f mm, worst deviation from the mesh offset %.5f mm\n", segs.size(), biggest, worst);
    assert(worst < 0.002 && biggest > 0.05);
  }
  // 5. G2/G3 with R: the same circle as with the centre offsets, both directions, and the bigger arc with a negative R
  {
    for (int cw = 0; cw < 2; cw++)
      for (int big = 0; big < 2; big++) {
        // circle of radius 30 around (5, -4); start at angle a0, end at angle a1 (the sweep is < 180 degrees or more than 180)
        float cx = 5, cy = -4, R = 30;
        float a0 = 20 * M_PI / 180, sweep = (big ? 250 : 100) * M_PI / 180;
        float a1 = cw ? a0 - sweep : a0 + sweep;
        float sx = cx + R * cos(a0), sy = cy + R * sin(a0), ex = cx + R * cos(a1), ey = cy + R * sin(a1);
        float o0, o1;
        // the sweep > 180 degrees takes a negative R
        bool ok = arc_offsets_from_radius(ex - sx, ey - sy, big ? -R : R, cw, o0, o1);
        printf("R form %s %s: centre offset (%.3f, %.3f), expected (%.3f, %.3f)\n", cw ? "G2" : "G3", big ? "big" : "small", o0, o1, cx - sx, cy - sy);
        assert(ok && fabs(o0 - (cx - sx)) < 1e-3 && fabs(o1 - (cy - sy)) < 1e-3);
      }
    float a, b;
    assert(!arc_offsets_from_radius(100, 0, 40, 1, a, b));  // the points are too far apart for the radius
    assert(!arc_offsets_from_radius(0, 0, 40, 1, a, b));    // the same point
    assert(arc_offsets_from_radius(80, 0, 40, 1, a, b) && fabs(a - 40) < 1e-3 && fabs(b) < 1e-3);  // a half circle
  }
  // 6. arcs in the XZ and YZ planes (with a helix along the third axis), a full circle, small and big radii: every piece is on the circle
  {
    struct Case { const char *name; uint8_t a0, a1, lin; float start[3], end[3], off[3]; float radius; uint8_t cw; };
    Case cases[] = {
      {"XY helix r=40", X_AXIS, Y_AXIS, Z_AXIS, {40, 0, 10}, {0, 40, 14}, {-40, 0, 0}, 40, 0},
      {"XZ arc r=20", X_AXIS, Z_AXIS, Y_AXIS, {20, 5, 30}, {0, 15, 50}, {-20, 0, 0}, 20, 0},
      {"YZ arc r=25", Y_AXIS, Z_AXIS, X_AXIS, {0, 25, 30}, {10, 0, 55}, {0, -25, 0}, 25, 1},
      {"XY full circle r=3", X_AXIS, Y_AXIS, Z_AXIS, {10, 10, 5}, {10, 10, 5}, {-3, 0, 0}, 3, 1},
      {"XY half circle r=70", X_AXIS, Y_AXIS, Z_AXIS, {-35, 0, 5}, {35, 0, 5}, {35, 0, 0}, 35, 0},
    };
    for (auto &c : cases) {
      segs.clear();
      float pos[4] = {c.start[0], c.start[1], c.start[2], 0}, tgt[4] = {c.end[0], c.end[1], c.end[2], 2.0f}, off[4] = {c.off[0], c.off[1], c.off[2], 0};
      mc_arc(pos, tgt, off, c.a0, c.a1, c.lin, 40, c.radius, c.cw, 0);
      float cen0 = c.start[c.a0] + c.off[c.a0], cen1 = c.start[c.a1] + c.off[c.a1];
      double worst = 0, len = 0, longest = 0;
      for (auto &s : segs) {
        double rr = hypot(s.cart[c.a0] - cen0, s.cart[c.a1] - cen1);
        worst = fmax(worst, fabs(rr - c.radius));
        len += s.len;
        longest = fmax(longest, s.len);
      }
      Seg &last = segs.back();
      double miss = fmax(fabs(last.cart[0] - c.end[0]), fmax(fabs(last.cart[1] - c.end[1]), fabs(last.cart[2] - c.end[2])));
      printf("%-22s %3zu pieces, longest %.2f mm, worst distance from the circle %.4f mm, ends %.4f mm from the target, E %.3f\n", c.name, segs.size(), longest, worst, miss, last.e);
      assert(worst < 0.01 && miss < 0.01 && fabs(last.e - 2.0f) < 1e-4);
      assert(longest <= ARC_MAX_SEGMENT_MM + 0.01 && longest >= 0.5);
    }
  }
  puts("arcs and reach OK");
  return 0;
}
